// Lumenmorph and Slidebox are loaded for this playground.
const { trackPointer, enhanceSlideboxRange, enhanceSlideboxRangeFill } =
  LumenExample;
const controller = new AbortController();
const stopLight = trackPointer(document.querySelector(".lm-lab"));
const ranges = [...document.querySelectorAll("input[type=range]")].flatMap(
  (input) => [enhanceSlideboxRange(input), enhanceSlideboxRangeFill(input)],
);

(function (demo, signal) {
  const input = demo.querySelector("[data-search]");
  const buttons = [...demo.querySelectorAll("[data-material]")];
  const colors = { Ember: "#ffaa71", Lagoon: "#70d5c5", Moonstone: "#d5c7ec" };
  input.addEventListener(
    "input",
    () => {
      for (const button of buttons)
        button.hidden = !button.dataset.material
          .toLowerCase()
          .includes(input.value.trim().toLowerCase());
      demo.querySelector("[data-no-results]").hidden = buttons.some(
        (button) => !button.hidden,
      );
    },
    { signal },
  );
  for (const button of buttons)
    button.addEventListener(
      "click",
      () => {
        for (const other of buttons)
          other.setAttribute("aria-pressed", String(button === other));
        demo.style.setProperty(
          "--lumen-glow-color",
          colors[button.dataset.material],
        );
        demo.querySelector(".command-status").textContent =
          `${button.dataset.material} selected`;
      },
      { signal },
    );
})(document.querySelector(".showcase-demo"), controller.signal);

window.addEventListener("pagehide", (event) => {
  if (!event.persisted) {
    controller.abort();
    stopLight();
    ranges.forEach((stop) => stop());
  }
});
